INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1012, '数学', '三年级', '选择', 2, '{"stem": "下列选项中，哪一组算式合并后得到的综合算式是“272−(141−72)”？正确的答案是（ ）。A. 141−72=69，272−69=203  B. 272−141=131，131−72=59  C. 272−72=200，200−141=59  D. 141−72=69，272+69=341", "options": null}', 'A', '综合算式 272−(141−72) 应先算括号内 141−72=69，再算 272−69=203，对应 A 组。', 'paper', '["practice", "VG-G3-1-4", "ykl3sx", "单元练习1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1011, '数学', '三年级', '选择', 2, '{"stem": "如果□=4，◎=9，○=15，下列算式中正确的是（ ）。A. ○+◎−□=30  B. ○−(◎+□)=2  C. ○−(◎−□)=2  D. □×◎−○=10", "options": null}', 'B', '逐项代入：A.15+9−4=20≠30；B.15−(9+4)=15−13=2✓；C.15−(9−4)=15−5=10≠2；D.4×9−15=21≠10。选 B。', 'paper', '["practice", "VG-G3-1-3", "ykl3sx", "单元练习1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
