INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "妈妈买了一件衬衫188元，买的一条裙子比衬衫便宜59元。妈妈一共花了多少元？", "options": null}', '317元', '裙子：188−59=129（元）；共：188+129=317（元）。综合算式：188+(188−59)=317。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "单元练习1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "食品公司有一批饮料，分装成1200箱运往超市。现在有6辆厢式货车，每辆货车最多能装203箱饮料。一次运得完吗？", "options": null}', '运得完', '203>200，6辆车至少可运 200×6=1200（箱），实际 203×6=1218（箱）>1200 箱，所以一次能运完。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "单元练习1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "学校组织二年级152名学生去游乐园游玩，准备乘坐观光车（每批含1辆红色车和1辆蓝色车；红色车限坐85人，蓝色车限坐98人）。（1）二年级学生能乘坐同一批观光车游览吗？", "options": null}', '能', '85+98=183（人），183>152，所以能乘坐同一批观光车游览。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "单元练习1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "游乐园价目表：海盗船10元/人，太空漫步20元/辆。小海一组共6人玩“海盗船”项目，小海付给收银员100元。（2）应找回多少元？", "options": null}', '40元', '6人海盗船费用：6×10=60（元）；找回：100−60=40（元）。综合算式：100−6×10=40。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "单元练习1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "游乐园价目表：海盗船10元/人，太空漫步20元/辆（每辆车可坐2人）。小海一组6人玩海盗船后还想玩太空漫步，出发前每人交给小海20元。（3）他们玩太空漫步剩下的钱够吗？", "options": null}', '够', '每人交20元共：20×6=120（元）；扣海盗船费用后剩：120−6×10=60（元）；太空漫步需 6÷2=3（辆），3×20=60（元）；60元=60元，够。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "单元练习1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "要开家长会了，小海和小华忙着排椅子：小海负责排单人椅（已排52把），小华负责排双人椅（已排20把）。今天有100位家长来开会，他们排的这些椅子够了吗？", "options": null}', '不够', '单人椅52个座位，双人椅20×2=40个座位，共 52+40=92（个）<100，不够。综合算式：52+20×2=92。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "单元练习1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "小明一家今年的年龄：小明9岁，妈妈35岁，爸爸37岁。（1）再过多少年，母子俩的年龄之和是50岁？", "options": null}', '3年', '母子俩今年年龄和：9+35=44（岁）；还差 50−44=6（岁）；母子俩每年共长2岁：6÷2=3（年）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "单元练习1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "小明一家今年的年龄：小明9岁，妈妈35岁，爸爸37岁。（2）再过多少年，爸爸的年龄除以3正好是小明的年龄？", "options": null}', '5年', '爸爸和小明相差 37−9=28（岁），年龄差不变。当爸爸年龄是小明的3倍时，小明 28÷(3−1)=14（岁），14−9=5（年）。验算：5年后爸爸42岁，42÷3=14。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "单元练习1"]', NULL, 0);
